Themify_Enqueue_Assets::$mediaMaxWidth=false;

function themify_theme_enqueue_footer(){
	// Get theme version for Themify theme scripts and styles
	$theme_version = Themify_Enqueue_Assets::$themeVersion;
	// Check split scroll & disable it on mobile and customizer
	$split_scroll = themify_theme_is_fullpage_scroll();

	// Prepare JS variables
	$themify_script_vars = array(
		'sticky_header'=>themify_theme_sticky_logo(),
		'pageLoaderEffect'=>themify_theme_has_page_loader()
	);
	// One Page Scroll
	if ( $split_scroll!==false ) {
	    Themify_Enqueue_Assets::loadThemeStyleModule( 'split',null,true);
	    if($split_scroll===true){
		    $themify_script_vars['splitScrollThreshold']=680;
		    $splitVer='0.2.3';
		    $themify_script_vars['s_p_v']=$splitVer;
		    Themify_Enqueue_Assets::addPrefetchJs(THEME_URI . '/js/modules/split/split.js',$theme_version);
		    Themify_Enqueue_Assets::addPrefetchJs(THEME_URI . '/js/modules/split/splitscroll.min.js',$splitVer);
	    }
	}
	else{
		$themify_script_vars['infinityEnabled']=(is_home() || is_archive() || themify_is_query_page() || is_search())?1:0;
		
		if($themify_script_vars['infinityEnabled']===1){
			$themify_script_vars['autoInfinite']=themify_check( 'setting-autoinfinite',true ) ? 'no': 'auto';
			$themify_script_vars['infiniteURL']=!themify_check( 'setting-infinite-url',true ) ? 1 :'';
		}
	}

	if(is_single() || is_singular('portfolio')){
		Themify_Enqueue_Assets::loadThemeStyleModule('single/single');
                if(is_single('post')){
                    Themify_Enqueue_Assets::loadThemeStyleModule('single/single-'.get_post_type());
                }
	}
	// Pass variable values to JavaScript
	wp_localize_script( 'themify-main-script', 'themifyScript', apply_filters( 'themify_script_vars', $themify_script_vars ) );

}
