/**
 * Adds page loading animation
 *
 * @since 1.0.0
 */
function themify_theme_add_split_loader() {
	if ( themify_theme_has_page_loader() ) :
            $color = themify_get_color('setting-page_loader_color',false,true);
            $icon = themify_get('setting-page_loader_icon',false,true);
            $cl = $bg = '';
            if($icon){
                // check if the value is a valid icon name
                $cl = themify_get_icon( $icon );
                // not an icon, it's an image
                if ( empty( $cl ) ) {
                    $cl='';
                    $bg = 'background:transparent url(' . $icon . ') center/cover no-repeat';
                }else{
                    $bg = 'background:0';
                }
            }
		Themify_Enqueue_Assets::loadThemeStyleModule('split-loader');
	?>
        <?php if($color || $bg):?>
        <style>
            <?php if($color):?>.split-loader,.hidden-view,body .split-panel{background-color:<?php echo $color ?>}<?php endif;?>
            <?php if($bg):?>.split-loader .split-spinner{<?php echo $bg ?>}<?php endif;?>
        </style>
    <?php endif;?>
	<?php if(themify_theme_is_fullpage_scroll()===true):?>
		<div class="split-panel split-right tf_h"></div>
		<div class="split-panel split-left tf_h"></div>
	<?php endif;?>
	<div class="split-loader tf_w tf_h tf_textc">
		<div class="split-spinner tf_rel"><?php echo $cl?></div>
	</div>
	<?php
	endif;
}

/**
 * Hook split loader to builder layout and layout part single page.
 * @since 1.1.7
 */
function themify_theme_split_loader_in_builder_layout_page() {
	if ( is_singular( array( 'tbuilder_layout', 'tbuilder_layout_part' ) ) ) {
		themify_theme_add_split_loader();
	}
}

/**
 * Checks if current page has split scroll.
 *
 * @since 1.0.0
 *
 * @return bool
 */
function themify_theme_is_fullpage_scroll() {
    static $is = NULL;
    if($is===null){
        $is = apply_filters( 'themify_theme_has_split_scroll', ( is_search() || !is_page() || ( isset( $_REQUEST['wp_customize'] ) && 'on' === $_REQUEST['wp_customize'] ) || ( is_admin() && 'customize.php' === basename( $_SERVER['PHP_SELF'] ) ) ) ? false : (is_page() && 'yes' === themify_get( 'split_scroll' )) );
	}
    return $is;
}

/**
 * Checks if current page has page loader effect.
 *
 * @since 1.0.0
 *
 * @return bool
 */
function themify_theme_has_page_loader() {
	$isSplit=themify_theme_is_fullpage_scroll();
    return $isSplit===true?true:($isSplit===false && 'on' !== themify_get( 'setting-page_loader_disabled',false,true ));
}



/**
 * Set portfolio post type slug
 *
 * @since 1.0.0
 *
 * @return string
 */
function themify_theme_portfolio_post_rewrite($slugs) {
	$slug = themify_get( 'themify_portfolio_slug','',true );
    if(is_array($slugs)){
        $slugs['post'] = empty( $slug ) ? apply_filters( 'themify_portfolio_rewrite', $slugs['post'] ) : $slug;
		$category_slug = themify_get( 'themify_portfolio_category_slug','',true );
		$slugs['tax'] = empty( $category_slug ) ? apply_filters( 'themify_portfolio_category_rewrite', $slugs['tax'] ) : $category_slug;    
    }else{
		$slugs = empty( $slug ) ? apply_filters( 'themify_portfolio_rewrite', 'project' ) : $slug;
    }
	return $slugs;
}
add_filter( 'themify_portfolio_post_rewrite', 'themify_theme_portfolio_post_rewrite' );

