function themify_theme_fixed_header() {
        static $is = NULL;
        if($is===null){
            if ( is_singular( array( 'post', 'page', 'portfolio' ) ) ) {
                    $fixed_header_field = themify_get( 'fixed_header' );
                    if ( 'yes' === $fixed_header_field ) {
                        $is = 'fixed-header';
                        return $is;
                    } elseif ( 'no' === $fixed_header_field ) {
                            $is = '';
                            return $is;
                    }
            }
            $is = themify_check( 'setting-fixed_header_disabled',true ) ? '' : 'fixed-header';
        }
        return $is;
}

function themify_theme_sticky_logo(){
     if(themify_theme_fixed_header()){
        global $themify_customizer;
        $logo = json_decode($themify_customizer->get_cached_mod('sticky_header_imageselect'));
        return !empty($logo->src)?$logo:false;
     }
     else{
         return false;
     }
}

/**
 * Additional classes for post and portfolio builder
 */
add_filter( 'themify_builder_module_loops_wrapper', 'themify_add_builder_classes', 10, 3 );
function themify_add_builder_classes($classes,$mod,$slug){

	if(isset($mod['layout_' . $slug] ) &&( $slug === 'post' || $slug === 'portfolio' ) ) {

		$is_portfolio = $slug === 'portfolio';
		$layout = $mod['layout_' . $slug];
		$masonry = $gutter = $content_layout = false;
		$content_layout = !empty($mod[$slug . '_content_layout'])
		&& $mod[$slug.'_content_layout'] !== 'no'
		&& ! in_array( $layout, array('list-large-image', 'list-thumb-image','grid2-thumb') )
			? $mod[$slug . '_content_layout'] : false;

		if( $content_layout === 'default' ) {
			$content_layout = themify_get( 'setting-' . $slug . '_content_layout','',true );
		}

		$gutter = ! empty( $mod[$slug . '_gutter'] )
		&& ! in_array( $layout
			, array(
				'list-post',
				'list-large-image',
				'list-thumb-image',
				'grid2-thumb',
				'slider',
				'fullwidth'
			),true ) ? $mod[$slug . '_gutter'] : false;

		if( $gutter === 'default' ) {
			$gutter = themify_get( 'setting-' . $slug . '_gutter',false,true);
		}

		$masonry = ( ! empty( $mod['disable_masonry'] )
			&& $mod['disable_masonry'] !== 'no'
			&& ! in_array( $layout
				, array(
					'list-post',
					'fullwidth',
					'auto_tiles',
					'list-large-image',
					'list-thumb-image',
					'grid2-thumb',
					'slider'
				),true ) ) ? 'masonry' : false;
		if( $masonry && $mod['disable_masonry'] === 'default' ) {
			$masonry = $is_portfolio
				? themify_get( 'setting-portfolio_disable_masonry',false,true )
				: themify_get( 'setting-disable_masonry',false,true );
			$masonry = $masonry === 'yes' ? 'masonry' : false;
		}

		if( $content_layout ) {
			$classes.=' '.$content_layout;
		}

		if( $gutter ) {
			$classes.=' '.$gutter;
		}

		if( $masonry ) {
			$classes.=' '.$masonry;
		}

	}
	return $classes;
}

function themify_theme_container_props($args,$post_type,$layout){
    if($layout!=='list-post' && $layout!=='list-thumb-image' && $layout!=='list-large-image' ){
	if($post_type==='product'){
	    if('no' !== themify_get( 'setting-product_disable_masonry',false,true )){
		$args['class'][]='masonry';
		$args['data-layout']='packery';
	    }
	}
	else{
	    $masonry = $post_type==='portfolio'? themify_get( 'setting-portfolio_disable_masonry',false,true ): themify_get( 'setting-disable_masonry',false,true );
	    if($masonry==='yes'){
		$args['class'][]='masonry';
	    }
	}
    }
    return $args;
}
add_filter('themify_container_props','themify_theme_container_props',10,3);

/**
 * Disable row animation effects on split scroll
 *
 * @return 	array
 */
function themify_theme_disable_row_animation( $attr, $settings, $builder_id ) {
    if ( $builder_id === get_queried_object_id() ) {
        unset( $attr['data-sticky-active'], $attr['data-lax'], $attr['data-lax-anchor'], $attr['data-lax-optimize'], $attr['data-lax-no-op'] );
    }
    return $attr;
}
/*Let the builder know that page is full section enabled*/
function themify_theme_builder_full_section($vars) {
    if(themify_theme_is_fullpage_scroll()) {
        $vars['is_fullSection']=true;
    }
    return $vars;
}
add_filter('themify_builder_active_vars','themify_theme_builder_full_section',10,1);